/** Общие константы ядра: пределы сервиса, таймеры, коды отказов. */

/** Предел длины одного текста сервиса (PSEUDONYMIZER_MAX_TEXT_CHARS по умолчанию). */
export const MAX_TEXT_CHARS = 70_000;
/** Сколько текстов клиент кладёт в одну пачку /pseudonymize_batch (ограничение клиента). */
export const BATCH_MAX_ITEMS = 100;
/** Поправка длины на каждый текст пачки, кроме первого (BATCH_ITEM_COST_CHARS сервиса). */
export const BATCH_ITEM_COST_CHARS = 100;
/** Доля окна, раньше которой граница разреза ищется «дальше» (иначе жёсткий разрез). */
export const SPLIT_SEARCH_MIN_SHARE = 0.5;
/** Перекрытие окон /check для длинного листа, символов (хватает на любой токен/значение). */
export const CHECK_OVERLAP_CHARS = 200;
/** Параллельных вызовов /check и /restore одного запроса. */
export const SERVICE_CONCURRENCY = 6;

/** Не чаще раза в столько мс опрашивается /health сервиса. */
export const HEALTH_POLL_MS = 5_000;
/** Бюджет кэша маскирования, символов (ключи плюс значения), как MASK_CACHE_MAX_CHARS. */
export const MASK_CACHE_MAX_CHARS = 4_000_000;
/**
 * Бюджет памяти восстановлений, символов (ключи плюс исходные строки модели): пары
 * «восстановленная строка -> как написала модель» для листьев, что вернутся в историю запроса.
 */
export const REMEMBER_CACHE_MAX_CHARS = 4_000_000;
/** Бюджет кэша результатов media-masker, символов base64 (~64 МБ ОЗУ). */
export const MEDIA_CACHE_MAX_CHARS = 64 * 1024 * 1024;
/** Длина шестнадцатеричного ключа кэша (sha256). */
export const CACHE_KEY_CHARS = 64;

/** Предел длины недописанного токена в потоке. */
export const MAX_PENDING_TOKEN_CHARS = 32;
/** Через сколько мс хвост, не похожий на начало токена, отдаётся как есть. */
export const PENDING_FLUSH_MS = 1_000;
/** Окно склейки восстановления в потоке, мс. */
export const RESTORE_WINDOW_MS = 300;
/** Сколько символов копится до восстановления независимо от окна. */
export const RESTORE_MAX_CHARS = 4_000;

/** Сколько символов sha256 session id попадает в журнал. */
export const SESSION_HASH_CHARS = 8;

/** HTTP-коды отказов (их несёт RequestRejectedError; ответы строит проект). */
export const STATUS_BAD_REQUEST = 400;
export const STATUS_UNSUPPORTED_ENCODING = 415;
export const STATUS_PII_FOUND = 422;
export const STATUS_BAD_GATEWAY = 502;
export const STATUS_UNAVAILABLE = 503;

/** Текст замены вложения при политике strip. */
export const ATTACHMENT_STRIPPED_TEXT =
  '[вложение скрыто политикой: изображения и PDF не передаются модели. Скажи пользователю, '
  + 'что файл тебе не показан, и попроси пересказать содержимое текстом]';

/**
 * Текст вместо вложения, которое не удалось замаскировать (fail closed). Причина - метка из
 * закрытого списка (BlockReason), без значений и имён файлов: ничего из вложения сюда не попадает.
 * Строка неизменна для одной причины: иначе ломается кэш промпта.
 */
export const attachmentBlockedText = (reason: string): string =>
  `[вложение скрыто: его не удалось проверить на персональные данные (причина: ${reason}). `
  + 'Скажи пользователю, что файл тебе не показан, и попроси пересказать содержимое текстом]';

/**
 * Тексты блока «что распознано на изображении». Неизменные строки: блок часть запроса, и от
 * его байт зависит кэш промпта.
 */
export const RECOGNIZED_HEADER =
  'Текст на изображении (распознан локально, персональные данные заменены метками):';
export const RECOGNIZED_QR_PREFIX = 'QR-код: ';
export const RECOGNIZED_BARCODE_PREFIX = 'Штрихкод: ';
export const RECOGNIZED_CODE_UNREAD =
  'не расшифрован, область на изображении закрашена';
export const RECOGNIZED_HIDDEN_NOTE =
  'На изображении есть нераспознанный рукописный текст, он скрыт.';

/** Текст вместо PDF, в котором не нашлось ни текста, ни страниц. */
export const EMPTY_DOCUMENT_TEXT = '[документ пуст]';
/** media_type PDF-документа. */
export const PDF_MEDIA_TYPE = 'application/pdf';

/** Системная вставка про токены (неизменная строка: иначе ломается кэш промпта). */
export const SYSTEM_INSERT_TEXT =
  'Служебная справка. В тексте встречаются токены вида [PERSON_1], [PHONE_2], [EMAIL_1]: '
  + 'это настоящие значения (имена, телефоны, почта), скрытые от тебя. Используй их как '
  + 'обычные имена и номера: не называй их заглушками, не обсуждай маскирование и не проси '
  + '«настоящие» данные. Если имя нужно в косвенном падеже, допиши код падежа в токене: '
  + '[PERSON_1|datv]. Коды: nomn, gent, datv, accs, ablt, loct. Метка в токене из текста '
  + 'запроса показывает падеж, в котором имя стояло в исходном тексте: считай имя стоящим '
  + 'в этом падеже и не исправляй его.';

/**
 * Сколько раз маскировать запрос, если boot_id сервиса сменился во время маскирования.
 * Второй подряд перезапуск - сервис нестабилен: отказ (fail closed), а не бесконечный повтор.
 */
export const MASK_BOOT_ATTEMPTS = 2;

/**
 * Сколько раз дозамаскировывать лист, в котором вторая линия (/check) нашла остаток ПДн.
 * Токены второго прохода меняют контекст детектора, поэтому после первой дозаливки бывает
 * ещё одна находка; сверх двух проходов лист скрывается целиком.
 */
export const REMASK_MAX_PASSES = 2;
/**
 * Текст вместо листа, в котором ПДн остались после дозамаскирования (fail closed без отказа
 * запросу). Неизменная строка: иначе ломается кэш промпта. Ничего из листа сюда не попадает.
 */
export const PII_HIDDEN_TEXT = '[скрыто: ПДн — содержимое не передано модели]';
/** Коды ошибок HTTP-клиента, которые значат «у сервиса нет такого маршрута» (старая версия). */
export const UNSUPPORTED_ROUTE_CODES: readonly string[] = ['http_404', 'http_405'];
